using System.Text.Json;
using Microsoft.Data.Sqlite;
using JobApplicationAgent.Application;
using JobApplicationAgent.Domain;
namespace JobApplicationAgent.Infrastructure;
public sealed class SqliteJobRepository(string connectionString):IJobRepository {
 SqliteConnection Open()=>new(connectionString);
 public async Task InitializeAsync(){ var path=new SqliteConnectionStringBuilder(connectionString).DataSource; var dir=Path.GetDirectoryName(path); if(!string.IsNullOrWhiteSpace(dir)) Directory.CreateDirectory(dir); await using var c=Open(); await c.OpenAsync(); var cmd=c.CreateCommand(); cmd.CommandText="""CREATE TABLE IF NOT EXISTS Jobs(ExternalId TEXT PRIMARY KEY,Title TEXT NOT NULL,Company TEXT NOT NULL,Location TEXT,Description TEXT,SalaryMin INTEGER,SalaryMax INTEGER,Currency TEXT NOT NULL,Source TEXT NOT NULL,SourceUrl TEXT NOT NULL,PublishedAt TEXT,FoundAt TEXT NOT NULL,Score INTEGER NOT NULL,MatchingSkills TEXT NOT NULL,MissingSkills TEXT NOT NULL,Explanation TEXT NOT NULL,Status TEXT NOT NULL DEFAULT 'Discovered',UpdatedAt TEXT NOT NULL); CREATE INDEX IF NOT EXISTS IX_Jobs_Score ON Jobs(Score DESC);"""; await cmd.ExecuteNonQueryAsync();
  // Migration: neue Spalten für bestehende Datenbanken (Daten bleiben erhalten).
  var existing=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  var info=c.CreateCommand(); info.CommandText="PRAGMA table_info(Jobs)";
  await using(var rd=await info.ExecuteReaderAsync()) while(await rd.ReadAsync()) existing.Add(rd.GetString(1));
  foreach(var col in new[]{"AppliedAt","ApplicationMethod","ApplicationNote"})
   if(!existing.Contains(col)){var alter=c.CreateCommand(); alter.CommandText=$"ALTER TABLE Jobs ADD COLUMN {col} TEXT"; await alter.ExecuteNonQueryAsync();}
 }
 public async Task UpsertAsync(JobPosting j,JobMatch m,CancellationToken ct=default){ await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="""INSERT INTO Jobs(ExternalId,Title,Company,Location,Description,SalaryMin,SalaryMax,Currency,Source,SourceUrl,PublishedAt,FoundAt,Score,MatchingSkills,MissingSkills,Explanation,Status,UpdatedAt) VALUES($id,$t,$c,$l,$d,$smin,$smax,$cur,$src,$url,$pub,$found,$score,$ms,$miss,$exp,'Discovered',$u) ON CONFLICT(ExternalId) DO UPDATE SET Title=$t,Company=$c,Location=$l,Description=$d,SalaryMin=$smin,SalaryMax=$smax,Currency=$cur,Source=$src,SourceUrl=$url,PublishedAt=$pub,Score=$score,MatchingSkills=$ms,MissingSkills=$miss,Explanation=$exp,UpdatedAt=$u;"""; Add(x,"$id",j.ExternalId);Add(x,"$t",j.Title);Add(x,"$c",j.Company);Add(x,"$l",j.Location);Add(x,"$d",j.Description);Add(x,"$smin",j.SalaryMin);Add(x,"$smax",j.SalaryMax);Add(x,"$cur",j.Currency);Add(x,"$src",j.Source);Add(x,"$url",j.SourceUrl);Add(x,"$pub",j.PublishedAt?.ToString("O"));Add(x,"$found",j.FoundAt.ToString("O"));Add(x,"$score",m.Score);Add(x,"$ms",JsonSerializer.Serialize(m.MatchingSkills));Add(x,"$miss",JsonSerializer.Serialize(m.MissingSkills));Add(x,"$exp",m.Explanation);Add(x,"$u",DateTimeOffset.UtcNow.ToString("O"));await x.ExecuteNonQueryAsync(ct); }
 public async Task<IReadOnlyList<JobView>> ListAsync(string? q=null,int minScore=0,string? status=null,CancellationToken ct=default){await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="SELECT * FROM Jobs WHERE Score >= $score AND ($q='' OR lower(Title||' '||Company||' '||coalesce(Description,'')) LIKE '%'||lower($q)||'%') AND ($status='' OR Status=$status) ORDER BY Score DESC, PublishedAt DESC LIMIT 500";Add(x,"$score",minScore);Add(x,"$q",q??"");Add(x,"$status",status??"");var r=await x.ExecuteReaderAsync(ct);var list=new List<JobView>();while(await r.ReadAsync(ct))list.Add(Read(r));return list;}
 public async Task<JobView?> GetAsync(string id,CancellationToken ct=default){await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="SELECT * FROM Jobs WHERE ExternalId=$id";Add(x,"$id",id);var r=await x.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?Read(r):null;}
 public async Task SetStatusAsync(string id,string status,CancellationToken ct=default){if(!ApplicationStatuses.All.Contains(status))throw new ArgumentException("Invalid status");await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="UPDATE Jobs SET Status=$s,UpdatedAt=$u,AppliedAt=CASE WHEN $s='Applied' AND AppliedAt IS NULL THEN $u ELSE AppliedAt END WHERE ExternalId=$id";Add(x,"$s",status);Add(x,"$u",DateTimeOffset.UtcNow.ToString("O"));Add(x,"$id",id);await x.ExecuteNonQueryAsync(ct);}
 public async Task SetApplicationDetailsAsync(string id,string? method,string? note,CancellationToken ct=default){await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="UPDATE Jobs SET ApplicationMethod=$m,ApplicationNote=$n WHERE ExternalId=$id";Add(x,"$m",string.IsNullOrWhiteSpace(method)?null:method.Trim());Add(x,"$n",string.IsNullOrWhiteSpace(note)?null:note.Trim());Add(x,"$id",id);await x.ExecuteNonQueryAsync(ct);}
 public async Task<Dictionary<string,int>> StatsAsync(CancellationToken ct=default){await using var c=Open();await c.OpenAsync(ct);var x=c.CreateCommand();x.CommandText="SELECT Status,count(*) FROM Jobs GROUP BY Status";var r=await x.ExecuteReaderAsync(ct);var d=ApplicationStatuses.All.ToDictionary(s=>s,_=>0);while(await r.ReadAsync(ct))d[r.GetString(0)]=r.GetInt32(1);return d;}
 static void Add(SqliteCommand c,string n,object? v)=>c.Parameters.AddWithValue(n,v??DBNull.Value);
 static JobView Read(SqliteDataReader r){string? S(string n)=>r[n] is DBNull?null:(string)r[n];int? I(string n)=>r[n] is DBNull?null:Convert.ToInt32(r[n]);var j=new JobPosting((string)r["ExternalId"],(string)r["Title"],(string)r["Company"],S("Location"),S("Description"),I("SalaryMin"),I("SalaryMax"),(string)r["Currency"],(string)r["Source"],(string)r["SourceUrl"],DateTimeOffset.TryParse(S("PublishedAt"),out var p)?p:null,DateTimeOffset.Parse((string)r["FoundAt"]));var m=new JobMatch(Convert.ToInt32(r["Score"]),JsonSerializer.Deserialize<string[]>((string)r["MatchingSkills"])??[],JsonSerializer.Deserialize<string[]>((string)r["MissingSkills"])??[],(string)r["Explanation"]);return new(j,m,(string)r["Status"],DateTimeOffset.TryParse(S("AppliedAt"),out var ap)?ap:null,S("ApplicationMethod"),S("ApplicationNote"));}
}
